#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int x = 10;                       // stack: automatic, freed at end of main
    int *y = malloc(sizeof *y);       // y itself is on the stack...
    if (!y) return 1;
    *y = 20;                          // ...the int it points to is on the heap
    printf("%d %d\n", x, *y);         // 10 20
    free(y);                          // heap block released by you
    return 0;
}

#include <stdio.h>

void print_down(int n) {
    if (n == 0) return;          // base case ends the descent
    printf("%d ", n);
    print_down(n - 1);           // each call pushes another frame
}

int main(void) {
    print_down(3);               // prints: 3 2 1
    return 0;
}

char *make_greeting(const char *name) {      // caller owns the result
    size_t n = strlen(name) + 8;
    char *s = malloc(n);
    if (s) snprintf(s, n, "Hello, %s", name);
    return s;
}
void fill_greeting(char *out, size_t cap, const char *name) {   // caller owns out
    snprintf(out, cap, "Hello, %s", name);
}
